/* @autogenerated */
import { ErrorPageComponent } from './error-page.component';

describe('ErrorPageComponent', () => {
  let component: ErrorPageComponent;

  beforeEach(() => {
    component = new ErrorPageComponent();
  });

  // ── responseMessage ────────────────────────────────────────────────────────

  describe('responseMessage()', () => {
    it('returns error.error.message when present', () => {
      component.error = { error: { message: 'Boom' } };
      expect(component.responseMessage()).toBe('Boom');
    });

    it('returns the string directly when error.error is a string', () => {
      component.error = { error: 'Plain error' };
      expect(component.responseMessage()).toBe('Plain error');
    });

    it('returns JSON.stringify when error.error is an object without message', () => {
      component.error = { error: { code: 42 } };
      expect(component.responseMessage()).toBe('{"code":42}');
    });

    it('returns "No message" when error has no error payload', () => {
      component.error = {};
      expect(component.responseMessage()).toBe('No message');
    });
  });

  // ── prefix ─────────────────────────────────────────────────────────────────

  describe('prefix()', () => {
    it('returns "no_empty_" when error[0].description is "not-empty"', () => {
      component.error = { error: [{ description: 'not-empty' }] };
      expect(component.prefix()).toBe('no_empty_');
    });

    it('returns "" when error[0].description is something else', () => {
      component.error = { error: [{ description: 'other' }] };
      expect(component.prefix()).toBe('');
    });

    it('returns "" when error.error has no [0] element', () => {
      component.error = { error: { message: 'something' } };
      expect(component.prefix()).toBe('');
    });

    it('returns "" when error.error is falsy', () => {
      component.error = {};
      expect(component.prefix()).toBe('');
    });
  });

  // ── sufix ──────────────────────────────────────────────────────────────────

  describe('sufix()', () => {
    it('returns "-no-empty" when error[0].description is "not-empty"', () => {
      component.error = { error: [{ description: 'not-empty' }] };
      expect(component.sufix()).toBe('-no-empty');
    });

    it('returns "" when error[0].description is something else', () => {
      component.error = { error: [{ description: 'other' }] };
      expect(component.sufix()).toBe('');
    });

    it('returns "" when error.error has no [0] element', () => {
      component.error = { error: { message: 'something' } };
      expect(component.sufix()).toBe('');
    });

    it('returns "" when error.error is falsy', () => {
      component.error = {};
      expect(component.sufix()).toBe('');
    });
  });

  // ── isUnknown ──────────────────────────────────────────────────────────────

  describe('isUnknown()', () => {
    it('returns true when error is null', () => {
      component.error = null;
      expect(component.isUnknown()).toBeTrue();
    });

    it('returns false when error.status is null', () => {
      component.error = { status: null };
      expect(component.isUnknown()).toBeFalse();
    });

    it('returns false when error.status is undefined', () => {
      component.error = {};
      expect(component.isUnknown()).toBeFalse();
    });

    it('returns false for each known status code', () => {
      for (const status of [0, 401, 402, 403, 404, 409, 422]) {
        component.error = { status };
        expect(component.isUnknown()).withContext(`status ${status}`).toBeFalse();
      }
    });

    it('returns true for an unknown status code', () => {
      component.error = { status: 500 };
      expect(component.isUnknown()).toBeTrue();
    });
  });
});
